import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const SubscriptionSuccessPage = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const subscriptionId = queryParams.get('subscriptionId');
    const invoiceId = queryParams.get('invoiceId');
    const [invoiceUrl, setInvoiceUrl] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchInvoice = async () => {
            try {
                const response = await fetch(`/paypal/generate-invoice`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ subscriptionId })
                });

                if (!response.ok) throw new Error('Invoice generation failed');

                const invoice = await response.json();
                setInvoiceUrl(invoice.links.find((link) => link.rel === 'self').href);
            } catch (error) {
                console.error('Failed to get invoice:', error);
            } finally {
                setIsLoading(false);
            }
        };

        if (subscriptionId && !invoiceId) {
            fetchInvoice();
        } else {
            setIsLoading(false);
        }
    }, [subscriptionId, invoiceId]);

    return (
        <div className="subscription-success-container">
            <div className="success-card">
                <div className="success-icon">✓</div>
                <h1>Subscription Activated!</h1>
                <p>Your subscription is now active. Thank you for joining us!</p>

                <div className="subscription-details">
                    <p>
                        <strong>Subscription ID:</strong> {subscriptionId}
                    </p>
                    {invoiceUrl && (
                        <p>
                            <strong>Invoice:</strong>
                            <a href={invoiceUrl} target="_blank" rel="noopener noreferrer">
                                Download Receipt
                            </a>
                        </p>
                    )}
                </div>

                <div className="actions">
                    <a href="/dashboard" className="btn btn-primary">
                        Go to Dashboard
                    </a>
                    <a href="/account/billing" className="btn btn-outline">
                        Manage Subscription
                    </a>
                </div>
            </div>
        </div>
    );
};

export default SubscriptionSuccessPage;
